WITH mun AS (SELECT * FROM UNNEST([STRUCT('2930766' AS id_municipio,'Sítio do Quinto' AS nome),STRUCT('2918100' AS id_municipio,'Jeremoabo' AS nome),STRUCT('2900355' AS id_municipio,'Adustina' AS nome),STRUCT('2929701' AS id_municipio,'Sátiro Dias' AS nome),STRUCT('2926509' AS id_municipio,'Ribeira do Amparo' AS nome),STRUCT('2909208' AS id_municipio,'Coronel João Sá' AS nome)])),car AS (SELECT REPLACE(id_imovel,'-','') id_car_norm,id_imovel,id_municipio,area FROM `basedosdados.br_sfb_sicar.area_imovel` JOIN mun USING(id_municipio) WHERE data_extracao>=DATE '2026-06-02' AND data_extracao<=DATE '2026-08-04' QUALIFY ROW_NUMBER() OVER(PARTITION BY REPLACE(id_imovel,'-','') ORDER BY data_extracao DESC)=1),p AS (SELECT DISTINCT ano_emissao,id_referencia_bacen,numero_ordem,REPLACE(id_car,'-','') id_car_norm FROM `basedosdados.br_bcb_sicor.recurso_publico_propriedade` WHERE ano_emissao BETWEEN 2013 AND 2026 AND id_car IS NOT NULL AND TRIM(id_car)!=''),n AS (SELECT ano_emissao,id_referencia_bacen,numero_ordem,COUNT(*) n_imoveis FROM p GROUP BY 1,2,3),b AS (SELECT op.ano_emissao,c.id_imovel,c.id_municipio,c.area,op.id_referencia_bacen,op.valor_parcela_credito/n.n_imoveis credito,op.area_financiada/n.n_imoveis area_financiada FROM p JOIN n USING(ano_emissao,id_referencia_bacen,numero_ordem) JOIN `basedosdados.br_bcb_sicor.operacao` op USING(ano_emissao,id_referencia_bacen,numero_ordem) JOIN car c USING(id_car_norm) WHERE op.ano_emissao BETWEEN 2013 AND 2026),tot AS (SELECT id_municipio,ano_emissao,SUM(credito) credito_total FROM b GROUP BY 1,2),micro AS (SELECT id_municipio,ano_emissao,COUNT(DISTINCT id_imovel) imoveis_micro,COUNT(DISTINCT id_referencia_bacen) operacoes_micro,COUNT(*) linhas_micro,SUM(credito) credito_micro,SUM(area_financiada) area_financiada_micro FROM b WHERE area<0.1 GROUP BY 1,2),areas AS (SELECT DISTINCT ano_emissao,id_municipio,id_imovel,area FROM b WHERE area<0.1),ac AS (SELECT ano_emissao,id_municipio,SUM(area) area_car_micro FROM areas GROUP BY 1,2) SELECT m.nome,t.ano_emissao,COALESCE(mi.imoveis_micro,0) imoveis_micro,COALESCE(mi.operacoes_micro,0) operacoes_micro,COALESCE(mi.linhas_micro,0) linhas_micro,COALESCE(mi.credito_micro,0) credito_micro,t.credito_total,SAFE_DIVIDE(mi.credito_micro,t.credito_total) participacao_micro,COALESCE(mi.area_financiada_micro,0) area_financiada_micro,COALESCE(ac.area_car_micro,0) area_car_micro,SAFE_DIVIDE(mi.area_financiada_micro,ac.area_car_micro) razao_areas FROM tot t JOIN mun m USING(id_municipio) LEFT JOIN micro mi USING(id_municipio,ano_emissao) LEFT JOIN ac USING(id_municipio,ano_emissao) ORDER BY m.nome,t.ano_emissao